<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $user = isset( $args['user'] ) ? $args['user'] : false; if ( ! $user ) { return; } ?><div class="sd-profile-cover"></div><div class="sd-profile-header"><img class="sd-profile-avatar" src="<?php echo esc_url( sd_avatar( $user->ID, 128 ) ); ?>" alt="<?php echo esc_attr( sd_member_display_name( $user->ID ) ); ?>"><div><h1><?php echo esc_html( sd_member_display_name( $user->ID ) ); ?></h1><?php if ( $user->user_url ) : ?><a href="<?php echo esc_url( $user->user_url ); ?>" rel="nofollow noopener" target="_blank"><?php echo esc_html( wp_parse_url( $user->user_url, PHP_URL_HOST ) ); ?></a><?php endif; ?></div><?php if ( get_current_user_id() === $user->ID ) : ?><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_auth_account_url() ); ?>"><?php esc_html_e( 'Edit profile', 'social-discovery' ); ?></a><?php endif; ?></div>
